class Solution {
    public List<Integer> findDisappearedNumbers(int[] nums){
        for(int item:nums){
            int index=Math.abs(item)-1;
            nums[index]=-Math.abs(nums[index]);
        }
        List<Integer> answer=new ArrayList<>();
        for(int i=0;i<nums.length;i++)if(nums[i]>0)answer.add(i+1);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findDisappearedNumbers(nums:IntArray):List<Int>{
        for(item in nums){
            val index=kotlin.math.abs(item)-1;
            nums[index]=-kotlin.math.abs(nums[index])
        };
        val answer=mutableListOf<Int>();
        for(i in nums.indices)if(nums[i]>0)answer.add(i+1);
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<int> findDisappearedNumbers(vector<int>& nums){
        for(int item:nums){
            int index=abs(item)-1;
            nums[index]=-abs(nums[index]);
        }
        vector<int> answer;
        for(int i=0;i<(int)nums.size();++i)if(nums[i]>0)answer.push_back(i+1);
        return answer;
    }
};
